import manifest from "@/content/screenshot-manifest.json";
import type { ProjectImageSlot } from "@/content/types";

type ScreenshotManifest = Record<string, Partial<Record<ProjectImageSlot, string>>>;
const screenshots = manifest as ScreenshotManifest;

/**
 * Returns the image extension for a real screenshot when one exists.
 * Backed by content/screenshot-manifest.json, which is regenerated by
 * `npm run screenshots` and before every dev/build.
 */
export function getProjectImageExtension(
  slug: string,
  slot: ProjectImageSlot,
): string | undefined {
  return screenshots[slug]?.[slot];
}

export function hasProjectImage(slug: string, slot: ProjectImageSlot): boolean {
  return getProjectImageExtension(slug, slot) !== undefined;
}
